import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Spell variants and glyphs","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/variants-and-glyphs.md","filePath":"en/guide/magic/variants-and-glyphs.md"}'),r={name:"en/guide/magic/variants-and-glyphs.md"};function s(o,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="spell-variants-and-glyphs" tabindex="-1">Spell variants and glyphs <a class="header-anchor" href="#spell-variants-and-glyphs" aria-label="Permalink to &quot;Spell variants and glyphs&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Learned glyphs can modify compatible Core Patterns with meaningful trade-offs.</li><li>A bounded complexity budget prevents unlimited stacking; exact combinations remain open.</li><li>Preparing a base spell does not automatically settle every variant’s memory requirements.</li></ul><p><a href="/Syrolands-Public/en/game-design/magic/variants-and-glyphs.html">Full design specification</a></p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role / boundary</th></tr></thead><tbody><tr><td>What glyphs change</td><td>Learned glyphs may change a known pattern&#39;s shape, delivery, targeting, effect or cost/stability. A tighter projectile, wider burst, lingering field or harder limb-focused cast are examples, not guaranteed spell options.</td></tr><tr><td>Limits and trade-offs</td><td>Every modifier needs a trade-off. Compatibility depends on the pattern, and a bounded complexity budget prevents unlimited stacking. Exact modifier counts and combinations remain undecided.</td></tr><tr><td>Memory and Inscription</td><td>A modified variant may need its own memory complexity or extra reconstruction effort; memorizing Fireball does not settle how every Fireball variant works. Inscription could preserve useful variants in physical scrolls or books.</td></tr><tr><td>Readable effects</td><td>Visuals should explain the difference: Compression might look tighter, Persistence might leave a visible field. <a href="/Syrolands-Public/en/game-design/magic/presentation.html">Modular presentation</a> is a design goal, not an implemented renderer. <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory</a> · <a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a>.</td></tr></tbody></table>',7)])])}const h=t(r,[["render",s]]);export{g as __pageData,h as default};
